// SignedMessage handling of edge-case message inputs
describe("Error Handling - SignedMessage", () => {
    test("Should handle missing timestamp gracefully", () => {
        const signedMessage = new SignedMessage({
            message: "test message",
            nonce: undefined,
            timestamp: undefined,
        })

        expect(signedMessage.timestamp).toBeUndefined()
        expect(signedMessage.message).toBe("test message")
    })

    test("Should handle empty message", () => {
        const signedMessage = new SignedMessage({
            message: "",
            nonce: undefined,
            timestamp: undefined,
        })

        expect(signedMessage.message).toBe("")
    })

    test("Should handle very long message", () => {
        const longMessage = "x".repeat(10000)
        const signedMessage = new SignedMessage({
            message: longMessage,
            nonce: undefined,
            timestamp: undefined,
        })

        expect(signedMessage.message).toBe(longMessage)
        expect(signedMessage.message.length).toBe(10000)
    })

    test("Should handle special characters in message", () => {
        const specialMessage = "Test with émojis 🔐 and special chars: !@#$%^&*()"
        const signedMessage = new SignedMessage({
            message: specialMessage,
            nonce: undefined,
            timestamp: undefined,
        })

        expect(signedMessage.message).toBe(specialMessage)
    })
})

// Encoding helpers on boundary and edge-case values
describe("TypeConversion - Edge Cases", () => {
    test("bigIntToBytes with zero", () => {
        const zero = 0n
        const bytes = Encoding.bigIntToBytes(zero)
        expect(bytes.length).toBe(0)
    })

    test("bigIntToBytes with maximum common sizes", () => {
        const testCases = [
            { value: 0xffn, expectedMinBytes: 1 }, // 255
            { value: 0xffffn, expectedMinBytes: 2 }, // 65535
            { value: 0xffffffn, expectedMinBytes: 3 }, // 16777215
            { value: 0xffffffffn, expectedMinBytes: 4 }, // 4294967295
        ]

        testCases.forEach(({ value, expectedMinBytes }) => {
            const bytes = Encoding.bigIntToBytes(value)
            expect(bytes.length).toBeGreaterThanOrEqual(expectedMinBytes)
        })
    })

    test("bytesToBigInt roundtrip with various sizes", () => {
        const testValues = [
            1n,
            255n,
            256n,
            65535n,
            65536n,
            1000000n,
            BigInt("99999999999999999999"),
        ]

        testValues.forEach((value) => {
            const bytes = Encoding.bigIntToBytes(value)
            const recovered = Encoding.bytesToBigInt(bytes)
            expect(recovered).toBe(value)
        })
    })

    test("bigIntToAsn1Hex with sign bit edge case", () => {
        // Values that need padding due to sign bit
        const testCases = [
            { value: 127n, shouldHavePadding: false }, // 0x7F (no padding needed)
            { value: 128n, shouldHavePadding: true }, // 0x80 (needs 0x0080)
            { value: 255n, shouldHavePadding: true }, // 0xFF (needs 0x00FF)
            { value: 0xffffn, shouldHavePadding: true }, // 0xFFFF
        ]

        testCases.forEach(({ value, shouldHavePadding }) => {
            const hex = Encoding.bigIntToAsn1Hex(value)
            if (shouldHavePadding) {
                expect(hex).toMatch(/^00/)
            } else {
                expect(hex).not.toMatch(/^00/)
            }
        })
    })

    test("hexToBuffer with various hex strings", () => {
        const testCases = [
            { hex: "00", expectedLength: 1 },
            { hex: "AABBCCDD", expectedLength: 4 },
            { hex: "0123456789ABCDEF", expectedLength: 8 },
            { hex: "FF", expectedLength: 1 },
        ]

        testCases.forEach(({ hex, expectedLength }) => {
            const buffer = Encoding.hexToBuffer(hex)
            expect(buffer.byteLength).toBe(expectedLength)
        })
    })

    test("base64ToBytes with padding variations", () => {
        const testCases = [
            "AQ==", // 1 (no padding)
            "Kg==", // 42 (with padding)
            "SGVsbG8=", // "Hello"
        ]

        testCases.forEach((base64) => {
            const bytes = Encoding.base64ToBytes(base64)
            expect(bytes).toBeInstanceOf(Uint8Array)
            expect(bytes.length).toBeGreaterThan(0)
        })
    })
})

// Decoding proofs and proof lists from JSON
describe("Proof Parsing - Edge Cases", () => {
    test("ProofD from JSON with minimal fields", () => {
        // a_responses[0] (secret key) and a_disclosed[1] (metadata) are required
        const minimalProof: ProofDJSON = {
            c: "AQ==",
            A: "AQ==",
            e_response: "AQ==",
            v_response: "AQ==",
            a_responses: { "0": "AQ==" },
            a_disclosed: { "1": "AQ==" },
        }

        const proof = ProofD.fromJSON(minimalProof)

        expect(proof.c).toBe(1n)
        expect(proof.a).toBe(1n)
        expect(proof.eResponse).toBe(1n)
        expect(proof.vResponse).toBe(1n)
        expect(proof.aResponses[0]).toBe(1n)
        expect(proof.aDisclosed[1]).toBe(1n)
    })

    test("ProofD.fromJSON fails closed on missing required entries", () => {
        const base = (): ProofDJSON => ({
            c: "AQ==",
            A: "AQ==",
            e_response: "AQ==",
            v_response: "AQ==",
            a_responses: { "0": "AQ==" },
            a_disclosed: { "1": "AQ==" },
        })

        const noSecretKey = base()
        noSecretKey.a_responses = {}
        expect(() => ProofD.fromJSON(noSecretKey)).toThrow()

        const noMetadata = base()
        noMetadata.a_disclosed = {}
        expect(() => ProofD.fromJSON(noMetadata)).toThrow()

        const noChallenge = base() as Partial<ProofDJSON>
        delete noChallenge.c
        expect(() => ProofD.fromJSON(noChallenge as ProofDJSON)).toThrow()
    })

    test("ProofList with multiple proofs", async () => {
        const proofList = new ProofList([])
        expect(proofList.proofList).toHaveLength(0)

        const message = await parseSessionResult(VALID_SIGNED_MESSAGE_JSON[0]!)
        expect(message.signature.proofList.length).toBeGreaterThan(0)
    })

    test("SignedMessage consistency check", async () => {
        const SignedMessage1: SignedMessage = await parseSessionResult(
            VALID_SIGNED_MESSAGE_JSON[0]!
        )
        const SignedMessage2: SignedMessage = await parseSessionResult(
            VALID_SIGNED_MESSAGE_JSON[0]!
        )

        expect(SignedMessage1).toStrictEqual(SignedMessage2)
    })
})

